import sys
import math
import heapq

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    b = int(input[1])
    a = list(map(int, input[2:2 + n]))

    bal = [0] * n
    for i in range(n):
        if i == 0:
            bal[i] = 1 if a[i] % 2 == 0 else -1
        else:
            bal[i] = bal[i - 1] + (1 if a[i] % 2 == 0 else -1)

    pq = []
    for i in range(1, n - 1):
        if bal[i] == 0:
            heapq.heappush(pq, abs(a[i + 1] - a[i]))

    ans = 0
    while pq and b >= pq[0]:
        b -= heapq.heappop(pq)
        ans += 1

    print(ans)

if __name__ == "__main__":
    main()

