def max_cuttings(arr, b):
    costs = []
    numEvens = 1 if arr[0] % 2 == 0 else 0
    numOdds = 1 if arr[0] % 2 == 1 else 0
    numCuttings = 0

    for i in range(1, len(arr)):
        if numOdds == numEvens and abs(arr[i] - arr[i - 1]) <= b:
            numEvens = 0
            numOdds = 0
            costs.append(abs(arr[i] - arr[i - 1]))
        if arr[i] % 2 == 0:
            numEvens += 1
        else:
            numOdds += 1

    costs.sort()

    for cost in costs:
        if b < cost:
            break
        numCuttings += 1
        b -= cost

    return numCuttings


