		nEven++;
	    }else{
		nOdd++;
	    }
	}
	if(nEven!=nOdd){
	    correct = false;
	}
	return correct;
    }

    int getMinAvailInd(int[]aArr, int nCoins, Hashtable<Integer,Boolean>cutUsed){
	int len = aArr.length;
	int minInd = -1;
