import sys

class Cutting:
    @staticmethod
    def strToIntArr(s):
        sArr = s.strip().split()
        return [int(x) for x in sArr]

    def checkSub(self, aArr, splitInd):
        correct = True
        nEven = 0
        nOdd = 0
        for i in range(splitInd + 1):
            el = aArr[i]
            if el % 2 == 0:
                nEven += 1
            else:
                nOdd += 1
        if nEven != nOdd:
            correct = False
        return correct

    def getMinAvailInd(self, aArr, nCoins, cutUsed):
        length = len(aArr)
        minInd = -1
        minCost = nCoins + 1
        for i in range(1, length - 1):
            cost = abs(aArr[i] - aArr[i + 1])
            if cost < minCost:
                if self.checkSub(aArr, i):
                    if i not in cutUsed:
                        minCost = cost
                        minInd = i
        return minInd

    def getMaxCuts(self, n, b, aArr):
        nCoins = b
        nCuts = 0
        cutUsed = set()
        while nCoins > 0:
            ind = self.getMinAvailInd(aArr, nCoins, cutUsed)
            if ind > -1:
                cutUsed.add(ind)
                cost = abs(aArr[ind] - aArr[ind + 1])
                nCoins -= cost
                nCuts += 1
            else:
                break
        return nCuts

def main():
