    for i in range(n):
        if match[i] == -1:
            p = [-1] * n
            v = find_path(graph, match, p, i)
            while v != -1:
                pv = p[v]
                ppv = match[pv]
                match[v] = pv
                match[pv] = v
                v = ppv
    return sum(1 for x in match if x != -1) // 2

def find_path(graph, match, p, root):
    n = len(graph)
    base = list(range(n))
    used = [False] * n
    q = []
    p[:] = [-1] * n

    used[root] = True
    q.append(root)
    while q:
        u = q.pop(0)
        for v in graph[u]:
            if base[u] == base[v] or match[u] == v:
                continue
            if v == root or (match[v] != -1 and p[match[v]] != -1):
                curbase = lca(match, base, p, u, v)
                blossom = [False] * n
                mark_path(match, base, blossom, p, u, curbase, v)
                mark_path(match, base, blossom, p, v, curbase, u)
                for i in range(n):
                    if blossom[base[i]]:
                        base[i] = curbase
                        if not used[i]:
                            used[i] = True
                            q.append(i)
            elif p[v] == -1:
                p[v] = u
                if match[v] == -1:
                    return v
                v2 = match[v]
                if not used[v2]:
                    used[v2] = True
                    q.append(v2)
    return -1

def mark_path(match, base, blossom, p, u, curbase, child):
    while base[u] != curbase:
        blossom[base[u]] = True
        blossom[base[match[u]]] = True
        p[u] = child
        u = p[match[u]]

def lca(match, base, p, a, b):
    used = [False] * len(match)
    while True:
        a = base[a]
        used[a] = True
        if match[a] == -1:
            break
        a = p[match[a]]
    while True:
        b = base[b]
        if used[b]:
            return b
        b = p[match[b]]

