class _1047D:
    def solve(self, in_stream, out_stream):
        n = in_stream.nextInt()
        m = in_stream.nextInt()

        ans = 0

        if n > 100:
            nn = (n - 100) % 6
            nq = (n - 100) // 6
            ans += nq * 6 * m
            n = 100 + nn

        if m > 100:
            nm = (m - 100) % 6
            mq = (m - 100) // 6
            ans += mq * 6 * n
            m = 100 + nm

        mat = [[0] * (m + 1) for _ in range(n + 1)]

        u = 1
        v = 1
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if (i + j) % 2 == 0:
                    mat[i][j] = u
                    u += 1

        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if (i + j) % 2 != 0:
                    mat[i][j] = v
                    v += 1

        g = [[] for _ in range(u)]

        def addEdge(i, j, s, t):
            if s <= 0 or t <= 0 or s > n or t > m:
                return
            g[mat[i][j]].append(mat[s][t])

        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if (i + j) % 2 == 0:
                    addEdge(i, j, i - 3, j)
                    addEdge(i, j, i - 2, j - 1)
                    addEdge(i, j, i - 2, j + 1)
                    addEdge(i, j, i, j - 3)
                    addEdge(i, j, i - 1, j - 2)
                    addEdge(i, j, i + 1, j - 2)
                    addEdge(i, j, i, j + 3)
                    addEdge(i, j, i - 1, j + 2)
                    addEdge(i, j, i + 1, j + 2)
                    addEdge(i, j, i + 3, j)
                    addEdge(i, j, i + 2, j - 1)
                    addEdge(i, j, i + 2, j + 1)

        bpm = HopcroftKarpBipartiteMatching(u - 1, v - 1, g)

        ans += 2 * bpm.maximumMatching()

        out_stream.println(ans)

class HopcroftKarpBipartiteMatching:
    def __init__(self, m, n, g):
        self.m = m
        self.n = n
        self.g = g
        self.pairU = [0] * (m + 1)
        self.pairV = [0] * (n + 1)
        self.dis = [0] * (m + 1)
        self.inf = 10**7
        self.NIL = 0

    def maximumMatching(self):
        for i in range(1, self.m + 1):
            self.pairU[i] = self.NIL
        for i in range(1, self.n + 1):
            self.pairV[i] = self.NIL

        maxMatching = 0

        while self.bfs():
            for i in range(1, self.m + 1):
                if self.pairU[i] == self.NIL and self.dfs(i):
                    maxMatching += 1
        return maxMatching

    def bfs(self):
        queue = deque()

        for i in range(1, self.m + 1):
            if self.pairU[i] == self.NIL:
                self.dis[i] = 0
                queue.append(i)
            else:
                self.dis[i] = self.inf

        self.dis[self.NIL] = self.inf

        while queue:
            u = queue.popleft()
            if self.dis[u] < self.dis[self.NIL]:
                for v in self.g[u]:
                    if self.dis[self.pairV[v]] == self.inf:
                        self.dis[self.pairV[v]] = self.dis[u] + 2
                        queue.append(self.pairV[v])

        return self.dis[self.NIL] < self.inf

    def dfs(self, u):
        if u != self.NIL:
            for v in self.g[u]:
                if self.dis[self.pairV[v]] == self.dis[u] + 2:
                    if self.dfs(self.pairV[v]):
                        self.pairV[v] = u
                        self.pairU[u] = v
                        return True
            self.dis[u] = self.inf
            return False
        return True

def main():
    in_stream = InputReader(sys.stdin)
    out_stream = OutputWriter(sys.stdout)
    solver = _1047D()
    solver.solve(in_stream, out_stream)

if __name__ == "__main__":
    main()

