            }
            if (i % 2 == 1) {
                for (int k = 0; k <= Math.min(i, 2 * n - i); k++) {
                    tWays = (tWays + ways[i][k]) % MOD;
                }
            }
        }
        System.out.println(tWays);
    }

    public static void main(String[] args) throws IOException {
        NekoAndAkiPrank solution = new NekoAndAkiPrank();
        solution.solve();
    }
}

