            if (dp0.containsKey(n)) {
                return dp0.get(n);
            }
            if (n == 1) {
                long res = even;
                dp0.put(n, res);
                return res;
            } else if (n == 2) {
                long res = (even * even + odd * odd) % MOD;
                dp0.put(n, res);
                return res;
            }
            long a1 = go(n / 2, 0);
            long a2 = go(n - n / 2, 0);
            long b1 = go(n / 2, 1);
            long b2 = go(n - n / 2, 1);
            long res = (a1 * a2 + b1 * b2) % MOD;
            dp0.put(n, res);
            return res;
        } else {
            if (dp1.containsKey(n)) {
                return dp1.get(n);
            }
            if (n == 1) {
