        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
//        System.out.println(Math.toDegrees(Math.acos(0.5)));
            int n = in.nextInt();
            if (n >= 100) {
                out.print(0);
            } else {
                int[] a = new int[105];
                int[] b = new int[105];
                int[] c = new int[105];
                int[] d = new int[105];
                int[] e = new int[105];
                for (int i = 1; i <= n; i++) {
                    a[i] = in.nextInt();
                    b[i] = in.nextInt();
                    c[i] = in.nextInt();
                    d[i] = in.nextInt();
                    e[i] = in.nextInt();
                }

                Set<Integer> bad = new HashSet<>();

                for (int i = 1; i <= n; i++) {
                    for (int j = 1; j <= n; j++) {
                        for (int k = 1; k <= n; k++) {
                            if (i == j || j == k || k == i) {
                                continue;
                            }

                            long ax = a[j] - a[i];
                            long bx = b[j] - b[i];
                            long cx = c[j] - c[i];
                            long dx = d[j] - d[i];
                            long ex = e[j] - e[i];

                            long ay = a[k] - a[i];
                            long by = b[k] - b[i];
                            long cy = c[k] - c[i];
                            long dy = d[k] - d[i];
                            long ey = e[k] - e[i];

                            double val = ax * ay + bx * by + cx * cy + dx * dy + ex * ey;
                            long m1 = ax * ax + bx * bx + cx * cx + dx * dx + ex * ex;
                            long m2 = ay * ay + by * by + cy * cy + dy * dy + ey * ey;
                            val = val / Math.sqrt(m1);
                            val = val / Math.sqrt(m2);
                            if (Math.toDegrees(Math.acos(val)) + 0.000000001 < 90) {
                                bad.add(i);
                            }
                        }
                    }
                }

                out.println(n - bad.size());

                for (int i = 1; i <= n; i++) {
                    if (!bad.contains(i)) {
                        out.println(i);
                    }
                }
            }
        }

    }

