                    }
                    if (c == '(') {
                        in_par = true;
                    }
                    if (c == ')') {
                        in_par = false;
                    }
                    word_len = 0;
                } else if (!in_word && !(c == '_' || c == '(' || c == ')')) {
                    in_word = true;
                    word_len++;
                } else if (in_word) {
                    word_len++;
                } else if (c == '(') {
                    in_par = true;
                } else if (c == ')') {
                    in_par = false;
                }
            }
