sys.setrecursionlimit(10**7)

N = 0
fifty = 0
hundred = 0
K = 0
memo = []
memo2 = []
comb = []

MOD = 10**9 + 7

def solve(t, f, h):
    global memo, fifty, hundred, K
    if f == 0 and h == 0:
        return 0
    if memo[t][f][h] != -1:
        return memo[t][f][h]
    if t == 1:
        if f < fifty:
            res = 1 + solve(0, f + 1, h)
        else:
            res = 1 + solve(0, f, h + 1)
        memo[t][f][h] = res
        return res
    ans = 10**6
    for i in range(f + 1):
        if i * 50 > K:
            break
        j = min((K - i * 50)//100, h)
        totalW = i * 50 + j * 100
        if (fifty - f + i > 0 and totalW > 50) or (hundred - h + j > 1 and totalW > 100) or (i == fifty and j == hundred):
            continue
        ans = min(ans, solve(1, f - i, h - j))
    memo[t][f][h] = ans + 1
    return memo[t][f][h]

def solve2(t, f, h, r):
    global memo2, combination
    if r == 0 and f == 0 and h == 0:
        return 1
    if r == 0:
        return 0
    if memo2[t][f][h][r] != -1:
        return memo2[t][f][h][r]
    ans = 0
    if t == 1:
        for i in range(fifty - f + 1):
            if i * 50 > K:
                break
            for j in range(hundred - h + 1):
                if i == 0 and j == 0:
                    continue
                totalW = i * 50 + j * 100
                if totalW > K:
                    break
                val = (comb[fifty - f][i] * comb[hundred - h][j]) % MOD
                val = (val * solve2(0, f + i, h + j, r - 1)) % MOD
                ans = (ans + val) % MOD
    else:
        for i in range(f + 1):
            if i * 50 > K:
                break
            for j in range(h + 1):
                if i == 0 and j == 0:
                    continue
                totalW = i * 50 + j * 100
                if totalW > K:
                    break
                val = (comb[f][i] * comb[h][j]) % MOD
                val = (val * solve2(1, f - i, h - j, r - 1)) % MOD
                ans = (ans + val) % MOD
    memo2[t][f][h][r] = ans
    return ans

def nCk(n, k):
    if n < k:
        return 0
    if k == 0 or k == n:
        return 1
    if comb[n][k] != -1:
        return comb[n][k]
    if n - k < k:
        comb[n][k] = nCk(n, n - k)
        return comb[n][k]
    comb[n][k] = (n * nCk(n - 1, k - 1) * pow_mod(k, MOD - 2, MOD)) % MOD
    return comb[n][k]

def pow_mod(x, p, m):
    result = 1
    x = x % m
    while p > 0:
        if p % 2 == 1:
            result = (result * x) % m
        x = (x * x) % m
        p //= 2
    return result

