        self.y = end

    def __hash__(self):
        return hash((self.x, self.y))

    def __eq__(self, other):
        if not isinstance(other, Point):
            return False
        return self.x == other.x and self.y == other.y

    def __lt__(self, o):
        return self.x - o.x

class FT:
    def __init__(self, n):
        self.data = [0] * n

    def update(self, index, value):
        while index < len(self.data):
            self.data[index] += value
            index += index & -index

    def get(self, index):
        result = 0
        while index > 0:
            result += self.data[index]
            index -= index & -index
        return result

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def pow_mod(a, b):
    if b == 0:
        return 1
    if b == 1:
        return a % MOD
    val = pow_mod(a, b // 2)
    if b % 2 == 0:
        return (val * val) % MOD
    else:
        return (val * (val * a % MOD)) % MOD

