class InputReader:
    def __init__(self, stream):
        self.stream = stream
        self.tokens = []

    def next(self):
        while not self.tokens:
            line = self.stream.readline()
            if not line:
                return ''
            self.tokens = line.strip().split()
        return self.tokens.pop(0)

    def nextDouble(self):
        return float(self.next())

    def nextInt(self):
        return int(self.next())

    def nextLong(self):
        return int(self.next())

    def nextByte(self):
        return bytes([int(self.next())])

