        else:
            isBalance = True
            break
    return isBalance

def getMass(mass):
    global arr
    if mass == 0:
        return 0
    logBase = 0
    if weight > 1:
        logBase = int(math.log(mass, weight))
    else:
        # Weight of 1 would make logs problematic, but assuming weight > 1 as in original code
        logBase = 0

    base_pow = Decimal(weight) ** (logBase + 1)
