    a=new long[40];
    int z=1;
    long temp=1;
    a[0]=1;
    if(w<=3)
    {
        System.out.println("YES");
        System.exit(0);
    }
    for(int i=1;i<16;i++)
    {
        a[z]=temp*w;
        temp=temp*w;
        if(temp>limit)
        {
            break;
        }
        z++;
    }

    leftsum=0;
    rightsum=m;
    n=z;
    pos(0);
    //System.out.println("hello");
    if(ans)
    {
        System.out.println("YES");
    }
    else
    {
        System.out.println("NO");
    }

}
public static void  pos(int x)
{
    if(x==n)
    {
        if(leftsum==rightsum)
        {
            //System.out.println("left sum is special "+leftsum+" rightsum is"+rightsum);
            ans=true;
        }
        return;
