import sys
import math

MOD = 998244353

def exp(a, e):
    result = 1
    base = a % MOD
    exponent = e
    while exponent > 0:
        if exponent & 1:
            result = (result * base) % MOD
        base = (base * base) % MOD
        exponent >>= 1
    return result

def gcd_ext(a, b):
    if a == 0 or b == 0:
        if a == 0:
            return (b, 0, 1)
        else:
            return (a, 1, 0)
    else:
        g, y, x = gcd_ext(b % a, a)
        return (g, x - (b // a) * y, y)

def inv(a, b):
    g, x, y = gcd_ext(a, b)
    return (x % b + b) % b

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    k = int(input_data[1])
    if k >= n:
        print(0)
        return
    fact = [1] * (n + 1)
    inv_fact = [1] * (n + 1)

    for i in range(1, n + 1):
        fact[i] = (i * fact[i - 1]) % MOD
        inv_fact[i] = inv(fact[i], MOD)

