	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter pw = new PrintWriter(System.out);

		int N = sc.ni();
		long K = sc.nl();
		if (K >= N) {
			pw.println(0);
			pw.close();
			return;
		}
		int C = (int)(N-K);

		fac = new long[200001];
		fac[0] = 1L;
		for (int i = 1; i <= 200000; i++)
			fac[i] = (i*fac[i-1])%MOD;

		long ans = 0;
		int sign = 1;
		for (int i = C; i > 0; i--) {
			long val = (choose(C,i)*power(i,N,MOD))%MOD;
			ans += sign*val;
			ans += 2*MOD;
			ans %= MOD;
			sign *= -1;
		}

		long mult = 2*choose(N,C);
