def BigMod(a, b, m):
    result = 1
    a = a % m
    while b > 0:
        if b % 2 == 1:
            result = (result * a) % m
        a = (a * a) % m
        b //= 2
    return result

def C(n, k, f):
    if k > n:
        return 0
    return f[n] * BigMod(f[k], MOD - 2, MOD) % MOD * BigMod(f[n - k], MOD - 2, MOD) % MOD

def solve(n, k, f):
    ans = 0
    for i in range(0, n - k + 1):
        if i % 2 == 0:
            ans = (ans + C(n - k, i, f) * BigMod(n - k - i, n, MOD) % MOD) % MOD
        else:
            ans = (ans - C(n - k, i, f) * BigMod(n - k - i, n, MOD) % MOD + MOD) % MOD
    return ans

