import sys

class NumberTheory:
    class Modulus:
        def __init__(self):
            self.factorial = [1]
            self.inv_factorial = [1]

        def modulus(self):
            raise NotImplementedError

        def fact(self, n):
            while len(self.factorial) <= n:
                self.factorial.append(self.mult(self.factorial[-1], len(self.factorial)))
            return self.factorial[n]

        def fInv(self, n):
            last_known = len(self.inv_factorial) - 1
            if last_known < n:
                fInv = [0] * (n - last_known)
                fInv[0] = self.inv(self.fact(n))
                for i in range(1, len(fInv)):
                    fInv[i] = self.mult(fInv[i - 1], n - i + 1)
                for i in reversed(range(len(fInv))):
                    self.inv_factorial.append(fInv[i])
            return self.inv_factorial[n]

        def paritySign(self, k):
            return 1 if k % 2 == 0 else self.modulus() - 1

        def ncr(self, n, r):
            if n < 0 or r < 0 or n < r:
                return 0
            return self.mult(self.fact(n), self.mult(self.fInv(r), self.fInv(n - r)))

        def normalize(self, x):
            x %= self.modulus()
            if x < 0:
                x += self.modulus()
            return x

        def add(self, a, b):
            v = a + b
            return v if v < self.modulus() else v - self.modulus()

        def mult(self, *args):
            r = 1
            for i in args:
                r = self.mult(r, i)
            return r

        def mult(self, a, b):
            return (a * b) % self.modulus()

        def pow(self, x, e):
            if e < 0:
                x = self.inv(x)
                e = -e
            result = 1
            base = x
            exp = e
            while exp > 0:
                if exp & 1:
                    result = self.mult(result, base)
                base = self.mult(base, base)
                exp >>= 1
            return result

        def inv(self, value):
            g = self.modulus()
            x, y = 0, 1
            r = value
            g_curr = g
            while r != 0:
                q = g_curr // r
                g_curr, r = r, g_curr % r
                x, y = y - q * x, x
            assert g_curr == 1
            return self.normalize(x)


