class Main:
    def __init__(self):
        self.read_input()

    def read_input(self):
        self.data_iter = iter(sys.stdin.read().split())

    def next(self):
        return next(self.data_iter)

    def Int(self):
        return int(self.next())

    def Long(self):
        return int(self.next())

    def Str(self):
        return self.next()

class Solution:
    def __init__(self, out, fs):
        self.out = out
        self.fs = fs
        self.INF = 2**31 - 1
        self.NINF = -2**31
        self.MOD = 998244353
        self.mod = 1000000007

    def solution(self, all, testcase):
        n = self.fs.Int()
        self.mod = self.fs.Int()

        # Initialize dp array
        max_j = n * n + 5
        dp = [[0] * max_j for _ in range(n)]
        dp[0][0] = 1

        for i in range(1, n):
            for j in range(max_j):
                for cnt in range(i + 1):
                    if j - cnt >= 0:
                        dp[i][j] += dp[i - 1][j - cnt]
                        dp[i][j] %= self.mod

        sums = [[0] * max_j for _ in range(n)]
        for i in range(n):
            total = 0
            for j in range(max_j):
                total += dp[i][j]
                total %= self.mod
                sums[i][j] = total

        # Precompute factorials
        fact = [1] * (501 * 501)
        for i in range(2, len(fact)):
            fact[i] = (fact[i - 1] * i) % self.mod

        # Precompute nCr
        ncr = [[0] * 501 for _ in range(501)]
        ncr[0][0] = 1
        for i in range(1, 501):
            ncr[i][0] = 1
            for j in range(1, 501):
                ncr[i][j] = (ncr[i - 1][j] + ncr[i - 1][j - 1]) % self.mod

        res = 0
        for i in range(n - 2, -1, -1):
            cnt = n - i
            pre = n - cnt
            com = (ncr[n][pre] * fact[pre]) % self.mod
            sum_value = 0
            for dif in range(1, cnt):
                for inv in range(dif, max_j):
