import sys
import math

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def add(self, o):
        return Point(self.x + o.x, self.y + o.y)

    def sub(self, o):
        return Point(self.x - o.x, self.y - o.y)

    def rotate(self, alpha):
        c = math.cos(alpha)
        s = math.sin(alpha)
        nx = self.x * c - self.y * s
        ny = self.x * s + self.y * c
        return Point(nx, ny)

    def norm(self):
        length = self.length()
        if length == 0:
            return Point(0, 0)
        return self.scale(1.0 / length)

    def scale(self, f):
        return Point(f * self.x, f * self.y)

    def length(self):
        return math.sqrt(self.x * self.x + self.y * self.y)

    def __str__(self):
        return "{:.6f} {:.6f}".format(self.x, self.y)

    def __eq__(self, o):
        eps = 1e-8
        return abs(self.x - o.x) < eps and abs(self.y - o.y) < eps

    def __lt__(self, o):
        eps = 1e-8
        if abs(self.x - o.x) > eps:
            return self.x < o.x
        if abs(self.y - o.y) > eps:
            return self.y < o.y
        return False

class Circle:
    def __init__(self, o, r):
        self.o = o
        self.r = r

    def contains(self, p):
        dist = p.sub(self.o).length()
        return abs(dist - self.r) < 1e-8

def intersect(c1, c2):
    dx = c1.o.x - c2.o.x
    dy = c1.o.y - c2.o.y
    d = math.sqrt(dx * dx + dy * dy)
    if d == 0:
        return None
    cos = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d)
    if cos < -1 - 1e-8:
        return None
    if cos < -1:
        cos = -1
    if cos > 1 + 1e-8:
        return None
    if cos > 1:
        cos = 1
    alpha = math.acos(cos)
    dir = c2.o.sub(c1.o).norm()
    res = []
    res.append(c1.o.add(dir.scale(c1.r).rotate(+alpha)))
    res.append(c1.o.add(dir.scale(c1.r).rotate(-alpha)))
    return res

def getId(p, pointId, adj):
    key = (round(p.x, 8), round(p.y, 8))
    if key not in pointId:
        sz = len(pointId)
        pointId[key] = sz
        adj.append([])
    return key

def dfs(i, was, adj):
    was[i] = True
    for j in adj[i]:
        if not was[j]:
            dfs(j, was, adj)

def main():
    input = sys.stdin.read().strip().split()
    n = int(input[0])
    index = 1
    circles = []
    for _ in range(n):
        x = int(input[index])
        y = int(input[index + 1])
        r = int(input[index + 2])
        index += 3
        circles.append(Circle(Point(x, y), r))
    all_points = set()

    for i in range(n):
        for j in range(i + 1, n):
            inter_points = intersect(circles[i], circles[j])
            if inter_points is None:
                continue
            for p in inter_points:
                all_points.add(p)

    pointId = {}
    adj = []

    for i in range(n):
        angles = [2 * math.pi * j / 3 for j in range(3)]
        circle = circles[i]
        for p in all_points:
            if circle.contains(p):
                dx = p.x - circle.o.x
                dy = p.y - circle.o.y
                alpha = math.atan2(dy, dx)
                if alpha < 0:
                    alpha += 2 * math.pi
                angles.append(alpha)
        angles = sorted(angles)
        dir = Point(1, 0).scale(circle.r)

        as_array = sorted(set(angles))
        for a in as_array:
            p = circle.o.add(dir.rotate(a))
            key = getId(p, pointId, adj)

        for j in range(len(as_array)):
            a1 = as_array[j]
            a2 = as_array[(j + 1) % len(as_array)]
            p = circle.o.add(dir.rotate(a1))
            q = circle.o.add(dir.rotate(a2))
            u = pointId[(round(p.x,8), round(p.y,8))]
            v = pointId[(round(q.x,8), round(q.y,8))]
            if u == v:
                continue
            adj[u].append(v)
            adj[v].append(u)

    v_size = len(pointId)
    e = 0
    for neighbors in adj:
        e += len(neighbors)
    e //= 2

    visited = [False] * v_size
    comps = 0
    for i in range(v_size):
        if not visited[i]:
            comps += 1
            dfs(i, visited, adj)

    print(1 + comps + e - v_size)

if __name__ == "__main__":
    main()

