import sys
import collections
import random

class DStress2:
    def __init__(self):
        self.INF = 10**9

    def solve(self):
        n = int(sys.stdin.readline())
        s = sys.stdin.readline().strip()
        print(self._solve(list(s)))

    def _stupid(self, s):
        st = ''.join(s)
        q = collections.deque()
        dist = {}
        q.append(st)
        dist[st] = 0
        while q:
            st = q.popleft()
            cur = dist[st]
            if 'VK' not in st:
                return cur
            for pos in range(len(st) - 1):
                next_str = st[:pos] + st[pos + 1] + st[pos] + st[pos + 2:]
                if next_str not in dist:
                    dist[next_str] = cur + 1
                    q.append(next_str)
        return 0

    def _count(self, index, start, kPos):
        ans = 0
        for i in range(start, len(kPos)):
            if kPos[i] < index:
                ans += 1
        return ans

    def _solve(self, s):
        vPos = []
        kPos = []
        otherPos = []

        for i, ch in enumerate(s):
            if ch == 'V':
                vPos.append(i)
            elif ch == 'K':
                kPos.append(i)
            else:
                otherPos.append(i)

        dp = [[[[self.INF for _ in range(len(otherPos)+1)] for _ in range(len(kPos)+1)] for _ in range(len(vPos)+1)] for _ in range(2)]
        dp[0][0][0][0] = 0

        for V in range(len(vPos)+1):
            for K in range(len(kPos)+1):
                for O in range(len(otherPos)+1):
                    for last in range(2):
                        cur = dp[last][V][K][O]
                        if cur == self.INF:
                            continue
                        # Place a V
                        if V < len(vPos):
                            new_cost = cur + self._count(vPos[V], K, kPos) + self._count(vPos[V], O, otherPos)
                            dp[1][V+1][K][O] = min(dp[1][V+1][K][O], new_cost)
                        # Place a K (only if last not K)
                        if K < len(kPos) and last == 0:
                            new_cost = cur + self._count(kPos[K], V, vPos) + self._count(kPos[K], O, otherPos)
                            dp[0][V][K+1][O] = min(dp[0][V][K+1][O], new_cost)
                        # Place other
                        if O < len(otherPos):
                            new_cost = cur + self._count(otherPos[O], V, vPos) + self._count(otherPos[O], K, kPos)
                            dp[0][V][K][O+1] = min(dp[0][V][K][O+1], new_cost)

        return min(dp[0][len(vPos)][len(kPos)][len(otherPos)], dp[1][len(vPos)][len(kPos)][len(otherPos)])

if __name__ == "__main__":
    dsp = DStress2()
    dsp.solve()

