import sys

def takeInt():
    return int(sys.stdin.readline().strip())

def takeStrings():
    return sys.stdin.readline().strip().split()

def takeInts():
    return list(map(int, takeStrings()))

def generateStrings(str_arr, n, dig):
    strs = [''] * n
    for i in range(n):
        if str_arr[i] == 'X':
            strs[i] = dig
        else:
            strs[i] = str_arr[i]
    return strs

def cal(str_arr, suffix, n, un):
    if n < 2:
        return 0
    last = suffix[1]
    first = suffix[0]
    if str_arr[n - 1] == '_' or str_arr[n - 1] == last:
        if str_arr[n - 2] == '_' or str_arr[n - 2] == first:
            return 10 ** un
    return 0

def solve(str_arr, n):
    if n == 1 or str_arr[0] == '0':
        return 0
    cnt = 0
    un = 0
    for i in range(1, n - 2):
        if str_arr[i] == '_':
            un += 1
    cnt += cal(str_arr, "25", n, un)
    cnt += cal(str_arr, "50", n, un)
    cnt += cal(str_arr, "75", n, un)

    if n > 2:
        if str_arr[0] == '_':
            cnt *= 9

    if n >= 3:
        if (str_arr[n - 1] == '_' or str_arr[n - 1] == '0') and (str_arr[n - 2] == '_' or str_arr[n - 2] == '0'):
            if n > 3:
                temp = 10 ** un
                if str_arr[0] == '_':
                    temp *= 9
                cnt += temp
            elif n == 3:
                if str_arr[0] == '_':
                    cnt += 9
                else:
                    cnt += 1
    return cnt

def main():
