    K = (1 << h) * 2
    H = ((K.bit_length() - 1) * 2)
    M = (K * K)//P

    wws = [0]*(1 << (h - 1))
    dw = pow(g, P-1 - (P-1)//n, P) if inverse else pow(g, (P-1)//n, P)
    w = (1 << 32) % P
