def garnerPrepare(m):
    n = len(m)
    if n == 0:
        return []
    gamma = [0]*n
    for k in range(1, n):
        prod = 1
        for i in range(k):
            prod = (prod * m[i]) % m[k]
        gamma[k] = invl(prod, m[k])
    return gamma

def garnerBatch(u, m, gamma):
    n = len(u)
    v = [0]*n
    v[0] = u[0]
    for k in range(1, n):
        temp = v[k-1]
        for j in range(k-2, -1, -1):
            temp = (temp * m[j] + v[j]) % m[k]
        v[k] = (u[k] - temp) * gamma[k] % m[k]
        if v[k] < 0:
            v[k] += m[k]
    return v

def modh(a, M, h, mod):
    r = a - (((M*(a & ((1 << 31) - 1)) >> 31) + M*(a >> 31)) >> (h - 31)) * mod
    return r if r < mod else r - mod

def invl(a, mod):
    b = mod
    p, q = 1, 0
    while b > 0:
        c = a // b
        d = a
        a, b = b, d % b
        d = p
        p, q = q, d - c * q
    return p if p >= 0 else p + mod

