def mod_pow(a, p):
    if p == 0:
        return 1
    half = mod_pow(a, p // 2)
    ans = (half * half) % MOD
    if p % 2 == 1:
        ans = (ans * a) % MOD
    return ans

def mod_inv(a):
    return mod_pow(a, MOD - 2)

def calc_roots(k, inverse):
    root = mod_pow(ROOT, mod_pow(2, twoPow - k))
    if inverse:
        root = mod_inv(root)
    roots = [0] * k
    if k > 0:
        roots[k - 1] = root
    for i in range(k - 1, 0, -1):
        roots[i - 1] = (roots[i] * roots[i]) % MOD
    return roots

def reorder_array(a, k):
    ans = [0] * len(a)
    for i in range(len(a)):
        ans[bit_reverse(i, k)] = a[i]
    return ans

def ntt(coef, k, inverse):
    coef = reorder_array(coef, k)
    roots = calc_roots(k, inverse)
    for s in range(k):
        length = 1 << s
        for st in range(0, len(coef), 2 * length):
            curRoot = 1
            for j in range(st, st + length):
                t = (curRoot * coef[j + length]) % MOD
                u = coef[j]
                coef[j] = (u + t) % MOD
                coef[j + length] = (u - t) % MOD
                curRoot = (roots[s] * curRoot) % MOD
    return coef

