    def toArray(self, l, r, data):
        if l == r:
            data[l] = self.min
            return
        self.pushDown()
        m = (l + r) // 2
        if self.left:
            self.left.toArray(l, m, data)
        if self.right:
            self.right.toArray(m + 1, r, data)

    def fromArray(self, l, r, data):
        if l == r:
            self.min = data[l]
            return
        self.dirty = False
        m = (l + r) // 2
        if not self.left:
            self.left = Node()
        if not self.right:
            self.right = Node()
        self.left.fromArray(l, m, data)
        self.right.fromArray(m + 1, r, data)
        self.pushUp()

    @staticmethod
    def build(l, r):
        node = Node()
        if l != r:
            m = (l + r) // 2
            node.left = Node.build(l, m)
            node.right = Node.build(m + 1, r)
        return node

    @staticmethod
    def query(f, t, l, r, node):
        if f > r or t < l:
            return INF
        if f <= l and r <= t:
            return node.min
        node.pushDown()
        m = (l + r) // 2
        return min(
            Node.query(f, t, l, m, node.left),
            Node.query(f, t, m + 1, r, node.right)
        )

    @staticmethod
    def update(i, l, r, val, node):
        if i > r or i < l:
            return
        if l == r:
            node.min = min(node.min, val)
            return
        node.pushDown()
        m = (l + r) // 2
        if not node.left:
            node.left = Node()
        if not node.right:
            node.right = Node()
        Node.update(i, l, m, val, node.left)
        Node.update(i, m + 1, r, val, node.right)
        node.pushUp()


def solve():
    n = int(input())
    k = int(input())

    intervals = [[0, 0]] + [[int(input()), int(input())] for _ in range(k)]
    intervals.append([2 * n, 2 * n])
    k += 1

    loop = [Node.build(0, n), Node.build(0, n)]
    data = [0] * (n + 1)

    for i in range(1, k+1):
        curDp = loop[i & 1]
        lastDp = loop[(i - 1) & 1]

        interval = intervals[i]
        intervalLength = interval[1] - interval[0]
        middleLength = interval[0] - intervals[i - 1][1]

        # Convert lastDp to array
        lastDp.toArray(0, n, data)
        array_length = min(len(data), intervalLength + middleLength)
        # Copy data with offset
        for idx in range(len(data) - 1, -1, -1):
            if idx + array_length <= n:
                data[idx + array_length] = data[idx]
        # Fill first part with INF
        for j in range(min(len(data), intervalLength + middleLength)):
            data[j] = INF

        minX = interval[1] - middleLength - intervalLength
        maxX = interval[1] - middleLength
        for j in range(n + 1):
            minNeedTime = Node.query(minX - j, maxX - j, 0, n, lastDp)
            data[j] = min(data[j], minNeedTime + 1)

        for j in range(n + 1):
            minNeedTime = Node.query(j - middleLength - intervalLength, j - middleLength, 0, n, lastDp)
            data[j] = min(data[j], minNeedTime + 2)

        # rebuild current DP from array
        curDp.fromArray(0, n, data)

    minFlipTime = Node.query(n, n, 0, n, loop[k & 1])
    if minFlipTime < INF:
        print("Full")
        print(minFlipTime)
    else:
        print("Hungry")


