import sys

def main():
    input_stream = sys.stdin
    output_stream = sys.stdout

    class FastScanner:
        def __init__(self, stream):
            self.stream = stream
            self.buffer = ''
            self.position = 0

        def read(self):
            if self.position >= len(self.buffer):
                self.buffer = self.stream.read(1024)
                self.position = 0
                if not self.buffer:
                    return -1
            ch = self.buffer[self.position]
            self.position += 1
            return ord(ch)

        def next(self):
            sb = []
            c = self.read()
            while self.isWhiteSpace(c):
                c = self.read()
            if c < 0:
                return None
            while c >= 0 and not self.isWhiteSpace(c):
                sb.append(chr(c))
                c = self.read()
            return ''.join(sb)

        @staticmethod
        def isWhiteSpace(c):
            return c >= 0 and c <= 32

    class FastPrinter:
        def __init__(self, out):
            self.out = out

        def println(self, s):
            self.out.write(str(s) + '\n')

        def close(self):
            self.out.flush()

    in_scanner = FastScanner(input_stream)
    out_printer = FastPrinter(output_stream)

    def solve():
        shift = 15
        maxn = 60

        INF = 10**9
        # Initialize dp with INF
        dp = [[[INF for _ in range(shift * 2 + 1)] for _ in range(maxn + 1)] for _ in range(maxn + 1)]
        dp[maxn][maxn][shift] = 0

        num_str = in_scanner.next()
        d = ("000" + num_str)[-len(num_str):]
        d_chars = list(d[::-1])  # reverse for iterating from least significant digit

        for ch in d_chars:
            digit = int(ch)
            # Prepare next DP array
            next_dp = [[[INF for _ in range(shift * 2 + 1)] for _ in range(maxn + 1)] for _ in range(maxn + 1)]
            for plus in range(maxn, -1, -1):
                for minus in range(maxn, -1, -1):
                    for carry in range(shift * 2 + 1):
                        val = dp[plus][minus][carry]
                        if val == INF:
                            continue
                        real_carry = carry - shift
                        curN = plus - minus + real_carry
                        curD = curN % 10
                        if curD < 0:
                            curD += 10
                        new_carry = (curN - curD) // 10
                        if curD != digit:
                            continue
                        if plus + minus + val < next_dp[plus][minus][new_carry + shift]:
                            next_dp[plus][minus][new_carry + shift] = plus + minus + val
            # Update dp for next iteration
            dp[:] = next_dp

        ans = INF
        for i in range(maxn + 1):
            for j in range(maxn + 1):
                if dp[i][j][shift] < ans:
                    ans = dp[i][j][shift]

        out_printer.println(ans)
        out_printer.close()

    solve()

if __name__ == "__main__":
    main()

