        # Initialize cumulative counts
        b = [True]
        for i in range(self.M):
            length = 1
            for j in range(self.FP[i]):
                length *= self.FP[i]
            c = b * length
            for k in range(0, length, self.FP[i]):
                for j2 in range(self.FP[i]):
                    c[k + j2] = False
            cnts = [0]
            for cval in c:
                cnts.append(cnts[-1] + (1 if cval else 0))
            self.cumps.append(cnts)
            self.FP[i] = length
            b = c

    def pi(self, x):
        if x <= self.cachelimit:
            ix = int(x)
            return self.xcums[ix >> 6] + bin(self.isp[ix >> 6] << (~ix)).count("1")
        # Cache lookup omitted for simplicity, in real solution should implement similar cache
        A = int(math.isqrt(math.isqrt(x)))
        if hasattr(self, 'picache'):
