# upsolve with rainboy
import sys

MD = 998244353

def init(n):
    ch = [[0] * (n + 1) for _ in range(n + 1)]
    ch[0][0] = 1
    for i in range(1, n + 1):
        ch[i][0] = 1
        for j in range(1, i + 1):
            ch[i][j] = (ch[i - 1][j] + ch[i - 1][j - 1]) % MD
    return ch

def power(a, k):
    if k == 0:
        return 1
    p = power(a, k // 2)
    p = p * p % MD
    if k % 2 == 1:
        p = p * a % MD
    return p

def main():
    input_line = sys.stdin.readline().strip()
    n, k, l = map(int, input_line.split())
    ch = init(n)

    pp = [0] * (2 * n + 1)
    qq = [0] * (2 * n + 1)
    aa = [0] * (2 * n + 1)

    pp[n] = power(2, n)

    for i in range(n):
        for j in range(2 * n, 0, -1):
            pp[j] = (pp[j] - pp[j - 1]) % MD

    for j in range(2 * n + 1):
        aa[j] = pp[j]

    inv2 = (MD + 1) // 2
    for i in range(1, n - k + 1):
        # qq := pp / p, where p = 2x (1 - x)
        for j in range(2 * n):
            qq[j] = pp[j + 1] * inv2 % MD
        qq[2 * n] = 0
        # divide by 1 - x: multiply by 1 + x + x^2 + ...
        for j in range(1, 2 * n + 1):
            qq[j] = (qq[j] + qq[j - 1]) % MD
