    m = n
    r1, r2 = 1, 0
    r3, r4 = 0, 1
    while a > 0 and n > 0:
        if n >= a:
            r3 -= r1 * (n // a)
            r4 -= r2 * (n // a)
            n = n % a
        else:
            a, n = n, a
            r1, r3 = r3, r1
            r2, r4 = r4, r2
    if a == 0:
        return r3 % m if r3 >= 0 else m + (r3 % m)
    else:
        return r1 % m if r1 >= 0 else m + (r1 % m)

