    input = sys.stdin.read().split()
    n = int(input[0])
    s = input[1]
    b = list(map(int, input[2:2+n]))
    string = list(s)

    letters = 26  # 'z' - 'a' + 1
    letCount = [0] * letters
    for ch in string:
        letCount[ord(ch) - ord('a')] += 1

    # Build the graph
    # Vertex offsets
    source = 0
    charOffset = 1
    pairOffset = charOffset + letters
    sinkOffset = pairOffset + n // 2
    sink = sinkOffset
    vNum = sinkOffset + 1

    g = Graph(vNum, source, sink)

    # Source -> Letters
    for i in range(letters):
        g.addEdge(source, charOffset + i, letCount[i], 0)
        for j in range(n // 2):
            c1 = string[j]
            c2 = string[n - j - 1]
            cost_val = -max(b[j], b[n - j - 1]) if c1 == c2 else -b[j] if c1 == chr(ord('a') + i) else (-b[n - j - 1] if c2 == chr(ord('a') + i) else 0)
            capacity = 1
            if c1 == chr(ord('a') + i):
                if c1 == c2:
                    g.addEdge(charOffset + i, pairOffset + j, capacity, cost_val)
                else:
                    g.addEdge(charOffset + i, pairOffset + j, capacity, -b[j]) if c2 != chr(ord('a') + i) else g.addEdge(charOffset + i, pairOffset + j, capacity, 0)
            else:
                if c2 == chr(ord('a') + i):
                    g.addEdge(charOffset + i, pairOffset + j, capacity, -b[n - j - 1])
                else:
                    g.addEdge(charOffset + i, pairOffset + j, capacity, 0)
    # Pairs -> Sink
    for i in range(n // 2):
        g.addEdge(pairOffset + i, sink, 2, 0)

    ans = g.getMinCostMaxFlow()
    print(-ans[1])

class Graph:
    def __init__(self, vNum, src, sink):
        self.vNum = vNum
        self.src = src
        self.sink = sink
        self.res = [[0] * vNum for _ in range(vNum)]
        self.cost = [[0] * vNum for _ in range(vNum)]
        self.costGraph = []
        self.d = [0] * vNum
        self.p = [0] * vNum

    def addEdge(self, from_, to, capacity, cost):
        self.res[from_][to] += capacity
        self.cost[from_][to] = cost
        self.cost[to][from_] = -cost

    def findCheapestPath(self):
        self.costGraph.clear()
        for i in range(self.vNum):
            for j in range(self.vNum):
                if self.res[i][j] > 0:
                    self.costGraph.append(Edge(i, j, self.cost[i][j]))
        for i in range(self.vNum):
            self.d[i] = float('inf')
            self.p[i] = -1
        self.d[self.src] = 0
        for _ in range(self.vNum - 1):
            changed = False
            for e in self.costGraph:
                if self.d[e.from] != float('inf') and self.d[e.from] + e.cost < self.d[e.to]:
                    self.d[e.to] = self.d[e.from] + e.cost
                    self.p[e.to] = e.from
                    changed = True
            if not changed:
                break
        return self.p[self.sink] != -1

    def augmentPath(self, from_, to, flow):
        pathCost = 0
        for cur in iterPath(to, from_, self.p):
            flow = min(flow, self.res[self.p[cur]][cur])
        for cur in iterPath(to, from_, self.p):
            self.res[self.p[cur]][cur] -= flow
            self.res[cur][self.p[cur]] += flow
            pathCost += self.cost[self.p[cur]][cur] * flow
        return [flow, pathCost]

    def getMinCostMaxFlow(self):
        flow = 0
        totalCost = 0
        while self.findCheapestPath():
            result = self.augmentPath(self.src, self.sink, float('inf'))
            flow += result[0]
            totalCost += result[1]
        return [flow, totalCost]

def iterPath(to, frm, p):
    path = []
    cur = to
    while cur != frm:
        path.append(cur)
        cur = p[cur]
    path.reverse()
    return path

class Edge:
    def __init__(self, from_, to, cost):
        self.from_ = from_
        self.to = to
        self.cost = cost

if __name__ == "__main__":
    main()

