def solve(n, k, s, t):
    while t % n != 0:
        delta = (1 if s < k else -1) * (t % n)
        s = (s + n + delta) % n
        t -= 1
    t //= n

    when_list = [-1] * n

    while t > 0:
        if when_list[s] != -1:
            period = when_list[s] - t
            for i in range(n):
                if when_list[i] != -1 and when_list[i] <= when_list[s] and when_list[i] % period == 0:
                    return i
            raise AssertionError()
        when_list[s] = t

        for i in range(n - 1, 0, -1):
            if s < k:
                s += i
                if s >= n:
                    s -= n
            else:
                s -= i
                if s < 0:
                    s += n
        t -= 1
    return s

def go(n, m):
    a = list(range(n))
    for i in range(n - 1, 0, -1):
        for j in range(n):
            delta = 1 if a[j] < m else -1
            a[j] = (a[j] + n + i * delta) % n
    return max_depth(a)

def max_depth(p):
    n = len(p)
    used = [-1] * n
    ret = 0
    for i in range(n):
        cur = 0
        v = i
        while used[v] != i:
            used[v] = i
            cur += 1
            v = p[v]
        ret = max(ret, cur)
    return ret

