			if (s < m) s += t % n;
			else s += n - t % n;
			s %= n;
			t--;
		}
		long cant = t / n;
		int prevs = s;
		while (cant > 0 && next[s] == -1) {
			for (int i = n - 1; i > 0; i--) {
				if (s < m) s += i;
				else s += n - i;
				if (s >= n) s -= n;
			}
			next[prevs] = s;
			prevs = s;
			cant--;
		}
		if (cant > 0) {
			long cicle = 1;
			prevs = s;
			while (next[prevs] != s) {
				cicle++;
				prevs = next[prevs];
			}
			long total = cant % cicle;
			for (int i = 0; i < total; i++) {
				s = next[s];
			}
		}
		out.println(s+1);

		out.flush();
	}

