			if (a<=b)
				return a+1;
			else
				return (2*a-b);

		int[] flag = new int[3*(a+b)+1];

		int temp=0;
		for (int i=1;i<=a;i++){
			flag[i]=i;
			temp=i;
		}

		for (int i=a+1;i<=a+b;i++){
